-- Models live in their own table. Without a row here the marker
-- spawns and is invisible, which is exactly what happened.
DELETE FROM `creature_template_model` WHERE `CreatureID` IN (990110, 990111, 990118, 990119, 990112, 990113, 990114, 990115, 990117);

-- What the pet knows. Creature.cpp copies these into m_spells, and
-- InitCharmCreateSpells puts each one on the pet bar with an autocast
-- toggle. A creature holds ONE list, so each rank is its own creature.
DELETE FROM `creature_template_spell` WHERE `CreatureID` IN (990111, 990117, 990118, 990119);

-- The Hero talent tab. `talenttab_dbc` and `talent_dbc` are world-table
-- overrides: DBCDatabaseLoader::Load ADDS and overrides by id, so the
-- stock 33 tabs and 892 talents are untouched. Column order is the DBC
-- field order, one column per character of the core's format string.
DELETE FROM `talenttab_dbc` WHERE `ID` = 990;

DELETE FROM `talent_dbc` WHERE `ID` BETWEEN 9000 AND 9022;


